import { createStyleContext } from "@styled-system/jsx"
import { Tabs as TabsPrimitive } from "radix-ui"

import { recipe } from "./recipe"

const { withContext, withProvider } = createStyleContext(recipe)

export const Root = withProvider(TabsPrimitive.Root, "root")

export const List = withContext(TabsPrimitive.List, "list")

export const Trigger = withContext(TabsPrimitive.Trigger, "trigger")

export const Content = withContext(TabsPrimitive.Content, "content")

import { sva } from "@styled-system/css"

export const recipe = sva({
  slots: ["root", "list", "trigger", "content"],
  base: {
    list: {
      display: "inline-flex",
      h: "10",
      alignItems: "center",
      justifyContent: "center",
      rounded: "md",
      bg: "layer.floating",
      p: "1",
      color: "foreground.emphasized",
    },
    trigger: {
      display: "inline-flex",
      alignItems: "center",
      justifyContent: "center",
      whiteSpace: "nowrap",
      rounded: "sm",
      px: "3",
      py: "1.5",
      textStyle: "sm",
      fontWeight: "medium",
      transition: "all",
      cursor: "pointer",

      _disabled: {
        pointerEvents: "none",
        opacity: "50%",
      },

      "&:is([data-state=active])": {
        bg: "background",
        color: "foreground",
        shadow: "sm",
      },
    },
    content: {
      mt: "2",
    },
  },
})

import { cn } from "@utils/cn"
import { Tabs as TabsPrimitive } from "radix-ui"
import {
  type ComponentPropsWithoutRef,
  type ElementRef,
  forwardRef,
} from "react"

import { tabs } from "./styles"

const styles = tabs()

export const Root = forwardRef<
  ElementRef<typeof TabsPrimitive.Root>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.Root>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Root
    ref={ref}
    className={cn(styles.root(), className)}
    {...props}
  />
))

Root.displayName = TabsPrimitive.Root.displayName

export const List = forwardRef<
  ElementRef<typeof TabsPrimitive.List>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.List>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.List
    ref={ref}
    className={cn(styles.list(), className)}
    {...props}
  />
))

List.displayName = TabsPrimitive.List.displayName

export const Trigger = forwardRef<
  ElementRef<typeof TabsPrimitive.Trigger>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Trigger
    ref={ref}
    className={cn(styles.trigger(), className)}
    {...props}
  />
))

Trigger.displayName = TabsPrimitive.Trigger.displayName

export const Content = forwardRef<
  ElementRef<typeof TabsPrimitive.Content>,
  ComponentPropsWithoutRef<typeof TabsPrimitive.Content>
>(({ className, ...props }, ref) => (
  <TabsPrimitive.Content
    ref={ref}
    className={cn(styles.content(), className)}
    {...props}
  />
))

Content.displayName = TabsPrimitive.Content.displayName

import { tv } from "tailwind-variants"

export const tabs = tv({
  slots: {
    root: "",
    list: "inline-flex h-10 items-center justify-center rounded-md bg-layer-floating p-1 text-foreground-emphasized",
    trigger:
      "inline-flex cursor-pointer items-center justify-center whitespace-nowrap rounded-sm px-3 py-1.5 text-sm font-medium transition-all disabled:pointer-events-none disabled:opacity-50 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm",
    content: "mt-2",
  },
})
